-- Запустіть у Neon SQL Editor після створення branch/backup.
-- Обидві транзакційні міграції в порядку: рахунки, типові операції.

-- ProOblik / 2026: план рахунків із наданого MHTML з аналітикою та кількісним обліком.
-- Перед запуском створіть резервну копію Neon. SQL транзакційний.
-- Додаткові колонки допускають NULL: невизначено у джерелі (це НЕ "ні").
-- analytic_enabled: true / false / null
-- analytic_dimensions: текст аналітичних розрізів зі сторінки
-- quantity_enabled: true / false / null
-- quantity_policy: текст правила зі сторінки ("за вашим рішенням" тощо)
-- Колонки додаються в public.accounts; програмний API поки не використовує їх.
BEGIN;
ALTER TABLE public.accounts ADD COLUMN IF NOT EXISTS analytic_enabled BOOLEAN;
ALTER TABLE public.accounts ADD COLUMN IF NOT EXISTS analytic_dimensions TEXT;
ALTER TABLE public.accounts ADD COLUMN IF NOT EXISTS quantity_enabled BOOLEAN;
ALTER TABLE public.accounts ADD COLUMN IF NOT EXISTS quantity_policy TEXT;

CREATE TEMP TABLE desired_accounts (
 code TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL,
 analytic_enabled BOOLEAN, analytic_dimensions TEXT,
 quantity_enabled BOOLEAN, quantity_policy TEXT
) ON COMMIT DROP;


-- Оновити записи (не змінює ID проводок і не перепроводить документи).
-- Якщо існують користувацькі рахунки, їх буде збережено, якщо на них є посилання.
SELECT code,name,kind,analytic_enabled,analytic_dimensions,quantity_enabled,quantity_policy
FROM desired_accounts
ON CONFLICT (code) DO UPDATE SET
 name=EXCLUDED.name, kind=EXCLUDED.kind,
 analytic_enabled=EXCLUDED.analytic_enabled,
 analytic_dimensions=EXCLUDED.analytic_dimensions,
 quantity_enabled=EXCLUDED.quantity_enabled,
 quantity_policy=EXCLUDED.quantity_policy;

-- Видалити лише зайві рахунки, які не використовуються у проводках.
-- Якщо інша таблиця має FK, рахунок зберігається; виняток перехоплюється.
-- Код 000 залишається: технічний рахунок введення залишків ProOblik.
DO $cleanup$
DECLARE r RECORD;
BEGIN
 FOR r IN SELECT a.code FROM public.accounts a
   WHERE a.code <> '000'
     AND NOT EXISTS (SELECT 1 FROM desired_accounts d WHERE d.code=a.code)
     AND NOT EXISTS (SELECT 1 FROM public.entries e WHERE e.debit_acc=a.code OR e.credit_acc=a.code)
 LOOP
  BEGIN
    DELETE FROM public.accounts WHERE code=r.code;
  EXCEPTION WHEN foreign_key_violation THEN
    RAISE NOTICE 'Збережено рахунок %: використовується в інших таблицях',r.code;
  END;
 END LOOP;
END $cleanup$;

-- Перевірка повноти міграції. Якщо кількості не збігаються, транзакція відкотиться.
DO $check$
DECLARE n INT;
BEGIN
 SELECT count(*) INTO n FROM desired_accounts d
 JOIN public.accounts a ON a.code=d.code
 WHERE a.name IS NOT DISTINCT FROM d.name
 AND a.kind IS NOT DISTINCT FROM d.kind
 AND a.analytic_enabled IS NOT DISTINCT FROM d.analytic_enabled
 AND a.analytic_dimensions IS NOT DISTINCT FROM d.analytic_dimensions
 AND a.quantity_enabled IS NOT DISTINCT FROM d.quantity_enabled
 AND a.quantity_policy IS NOT DISTINCT FROM d.quantity_policy;
 IF n <> 356 THEN RAISE EXCEPTION 'Migration verified % of 356 records',n; END IF;
END $check$;
COMMIT;

-- Діагностика після виконання; legacy – рахунки поза новим планом (потрібні історії).
SELECT count(*) AS total_accounts,
 count(*) FILTER (WHERE analytic_enabled IS TRUE) AS analytic_yes,
 count(*) FILTER (WHERE quantity_enabled IS TRUE) AS quantity_yes,
 count(*) FILTER (WHERE quantity_enabled IS NULL) AS quantity_not_specified
FROM public.accounts;
SELECT code,name,kind,analytic_enabled,analytic_dimensions,quantity_enabled,quantity_policy
FROM public.accounts WHERE code IN ('104','201','281','285','311','361','631','661','902') ORDER BY code;


-- ProOblik 2026: імпорт 472 початкових рядків; 2 дублікати і 2 спірні записи лишаються вимкненими.
-- Спершу створіть резервну копію/branch Neon; виконайте міграцію рахунків update_accounts_neon_analytics_2026.sql.
