BEGIN;
CREATE TABLE IF NOT EXISTS public.typical_operations (
 id SERIAL PRIMARY KEY, category TEXT NOT NULL,name TEXT NOT NULL,lines JSONB NOT NULL,
 sort INT NOT NULL DEFAULT 0,updated_by TEXT,updated_at TIMESTAMPTZ DEFAULT now()
);
