ALTER TABLE public.typical_operations ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE public.typical_operations ADD COLUMN IF NOT EXISTS family TEXT NOT NULL DEFAULT 'balanced';
ALTER TABLE public.typical_operations ADD COLUMN IF NOT EXISTS review_status TEXT NOT NULL DEFAULT 'approved';
ALTER TABLE public.typical_operations ADD COLUMN IF NOT EXISTS duplicate_of TEXT;
ALTER TABLE public.typical_operations ADD COLUMN IF NOT EXISTS note TEXT NOT NULL DEFAULT '';
ALTER TABLE public.typical_operations ADD COLUMN IF NOT EXISTS source_page TEXT NOT NULL DEFAULT '';
ALTER TABLE public.typical_operations ADD COLUMN IF NOT EXISTS source_status TEXT NOT NULL DEFAULT '';
CREATE UNIQUE INDEX IF NOT EXISTS typical_ops_uid_idx ON public.typical_operations(source_uid) WHERE source_uid IS NOT NULL;
CREATE INDEX IF NOT EXISTS typical_ops_active_idx ON public.typical_operations(is_active,category,sort,id);
-- ВАЖЛИВО: тільки один раз деактивуємо шаблони без source_uid, якщо новий набір ще не імпортовано.
DO $archive$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.typical_operations WHERE source_uid='P0001') THEN
  UPDATE public.typical_operations SET is_active=FALSE WHERE source_uid IS NULL;
 END IF;
END $archive$;
