$catalog$::jsonb) AS x(source_uid TEXT,category TEXT,name TEXT,lines JSONB,sort INT,family TEXT,review_status TEXT,is_active BOOLEAN,duplicate_of TEXT,note TEXT,source_page TEXT,source_status TEXT)
ON CONFLICT (source_uid) WHERE source_uid IS NOT NULL DO NOTHING;
DO $verify$ DECLARE n INT; BEGIN
 SELECT count(*) INTO n FROM public.typical_operations WHERE source_uid ~ '^P[0-9]{4}$';
 IF n < 472 THEN RAISE EXCEPTION 'Імпортовано лише % із 472 шаблонів',n; END IF;
END $verify$;
CREATE TABLE IF NOT EXISTS public.account_correspondences_291 (
 source_uid TEXT PRIMARY KEY,debit_acc TEXT NOT NULL,credit_acc TEXT NOT NULL,
 source_pages TEXT NOT NULL DEFAULT '',source_entry TEXT NOT NULL DEFAULT '',
 UNIQUE(debit_acc,credit_acc)
);
