CREATE TABLE IF NOT EXISTS public.offbalance_entries (
 id BIGSERIAL PRIMARY KEY,company_id INT NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,
 date DATE NOT NULL,doc TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',
 account_code TEXT NOT NULL REFERENCES public.accounts(code),
 direction TEXT NOT NULL CHECK(direction IN ('in','out')),
 amount NUMERIC(15,2) NOT NULL CHECK(amount>0),
 source_uid TEXT,created_by INT REFERENCES public.users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS offbalance_company_idx ON public.offbalance_entries(company_id,date,id);

-- Не дозволяємо списувати з позабалансового рахунку більше від наявного облікового залишку.
CREATE OR REPLACE FUNCTION public.prooblik_offbalance_nonnegative() RETURNS trigger AS $$
DECLARE available NUMERIC;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('offbalance:'||NEW.company_id||':'||NEW.account_code,0));
 IF NEW.direction='out' THEN
  SELECT COALESCE(SUM(CASE WHEN direction='in' THEN amount ELSE -amount END),0)
  INTO available FROM public.offbalance_entries
  WHERE company_id=NEW.company_id AND account_code=NEW.account_code AND date<=NEW.date;
  IF available<NEW.amount THEN
   RAISE EXCEPTION 'Недостатньо залишку позабалансового рахунку %: доступно %, списання %',NEW.account_code,available,NEW.amount;
  END IF;
 END IF;
 RETURN NEW;
END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS offbalance_nonnegative ON public.offbalance_entries;
CREATE TRIGGER offbalance_nonnegative BEFORE INSERT ON public.offbalance_entries
FOR EACH ROW EXECUTE FUNCTION public.prooblik_offbalance_nonnegative();
COMMIT;
-- Контроль: 472 імпортовані, 468 активних, 4 вимкнені (2 дублікати, 2 на перегляд).
SELECT review_status,is_active,count(*) FROM public.typical_operations WHERE source_uid LIKE 'P____' GROUP BY 1,2 ORDER BY 1,2;
